    -- Naxxramas: route notes, solo tips, and display names.
    ["After defeating ^Anub'Rekhan^, backtrack out of his room and take a left. Stay to the left while following the path to ^Grand Widow Faerlina^."] = "Après avoir vaincu ^Anub'Rekhan^, revenez sur vos pas pour sortir de sa salle, puis tournez à gauche. Restez à gauche et suivez le chemin jusqu'à ^Grand Widow Faerlina^.",
    ["After defeating ^Faerlina^, head southeast and follow the path back north all the way to ^Maexxna^."] = "Après avoir vaincu ^Faerlina^, partez vers le sud-est puis suivez le chemin qui remonte au nord jusqu'à ^Maexxna^.",
    ["After defeating ^Gothik the Harvester^, take the south exit and follow the path around to reach ^The Four Horsemen^."] = "Après avoir vaincu ^Gothik the Harvester^, prenez la sortie sud et suivez le chemin jusqu'à la rencontre des ^The Four Horsemen^.",
    ["After defeating ^Grobbulus^, exit south from the top of the room. Walk across a pipe as you follow the path around to find ^Gluth^."] = "Après avoir vaincu ^Grobbulus^, quittez le haut de la salle par le sud. Traversez un tuyau et suivez le chemin jusqu'à ^Gluth^.",
    ["After defeating ^Heigan^, exit to the east and follow the path around to ^Loatheb^."] = "Après avoir vaincu ^Heigan^, sortez par l'est et suivez le chemin jusqu'à ^Loatheb^.",
    ["After defeating ^Noth^, exit to the east and follow the path around to ^Heigan the Unclean^."] = "Après avoir vaincu ^Noth^, sortez par l'est et suivez le chemin jusqu'à ^Heigan the Unclean^.",
    ["After defeating ^Razuvious^, take the south exit and follow the path around to reach ^Gothik the Harvester^. Tag him to start the encounter."] = "Après avoir vaincu ^Razuvious^, prenez la sortie sud et suivez le chemin jusqu'à ^Gothik the Harvester^. Attaquez-le pour commencer le combat.",
    ["After defeating ^Thaddius^, click the ^Naxxramas Portal^."] = "Après avoir vaincu ^Thaddius^, cliquez sur le ^Naxxramas Portal^.",
    ["After defeating ^The Four Horsemen^, click the ^Naxxramas Portal^ to be teleported back to the entrance."] = "Après avoir vaincu ^The Four Horsemen^, cliquez sur le ^Naxxramas Portal^ pour être téléporté à l'entrée.",
    ["After killing ^Gluth^, follow the path straight ahead to reach ^Thaddius^."] = "Après avoir tué ^Gluth^, suivez le chemin tout droit jusqu'à ^Thaddius^.",
    ["After killing ^Loatheb^, click on the ^Naxxramas Portal^ to be teleported back to the entrance."] = "Après avoir tué ^Loatheb^, cliquez sur le ^Naxxramas Portal^ pour être téléporté à l'entrée.",
    ["After killing ^Maexxna^, click the ^Naxxramas Portal^ to return to the entrance."] = "Après avoir tué ^Maexxna^, cliquez sur le ^Naxxramas Portal^ pour retourner à l'entrée.",
    ["After killing ^Patchwerk^, follow the path and take a right to reach ^Grobbulus^."] = "Après avoir tué ^Patchwerk^, suivez le chemin puis tournez à droite pour rejoindre ^Grobbulus^.",
    ["After killing ^Sapphiron^, take the west exit and follow the path around to ^Kel'Thuzad^. Walk into the middle circle to begin the encounter."] = "Après avoir tué ^Sapphiron^, prenez la sortie ouest et suivez le chemin jusqu'à ^Kel'Thuzad^. Entrez dans le cercle central pour commencer le combat.",
    ["After returning to the entrance, take the southeast path towards ^The Plague Quarter^."] = "Après être revenu à l'entrée, prenez le chemin sud-est vers ^The Plague Quarter^.",
    ["After teleporting to ^Sapphiron's Lair^, proceed ahead to engage ^Sapphiron^."] = "Après vous être téléporté dans ^Sapphiron's Lair^, continuez tout droit pour affronter ^Sapphiron^.",
    ["After teleporting, click the ^Orb of Naxxramas^ right next to you."] = "Après la téléportation, cliquez sur l'^Orb of Naxxramas^ juste à côté de vous.",
    ["After teleporting, take the northwest exit toward ^The Construct Quarter^."] = "Après la téléportation, prenez la sortie nord-ouest vers ^The Construct Quarter^.",
    ["After teleporting, take the southwest path towards ^The Military Quarter^."] = "Après la téléportation, prenez le chemin sud-ouest vers ^The Military Quarter^.",
    ["After zoning in, take the northeast path to ^The Arachnid Quarter^."] = "En entrant, prenez le chemin nord-est vers ^The Arachnid Quarter^.",
    ["Ahead to Sapphiron"] = "Tout droit vers Saphiron",
    ["Backtrack then left to Faerlina"] = "Revenez en arrière, puis à gauche vers Faerlina",
    ["Click Naxxramas Portal"] = "Cliquez sur le portail de Naxxramas",
    ["Click Orb of Naxxramas"] = "Cliquez sur l'orbe de Naxxramas",
    ["East to Heigan"] = "À l'est vers Heigan",
